func cmdReviewVerify(root string, args []string, stdout, stderr io.Writer) int {
	jsonOutput, target := false, ""
	for _, arg := range args {
		if arg == "--json" {
			jsonOutput = true
		} else if strings.HasPrefix(arg, "-") || target != "" {
			fmt.Fprintln(stderr, "Usage: pose review verify <scope|bundle-id|bundle-path> [--json]")
			return 2
		} else {
			target = arg
		}
	}
	if target == "" {
		fmt.Fprintln(stderr, "Usage: pose review verify <scope|bundle-id|bundle-path> [--json]")
		return 2
	}
	store := cliGovernedStore(root)
	ref, err := resolveReviewBundleScope(store, target)
	if err != nil {
		fmt.Fprintf(stderr, "pose review verify: %v\n", err)
		return 1
	}
	verification, err := store.VerifyReviewBundle(ref)
	if err != nil {
		fmt.Fprintf(stderr, "pose review verify: %v\n", err)
		return 1
	}
	if jsonOutput {
		if code := writeJSON(stdout, verification); code != 0 {
			return code
		}
	} else {
		fmt.Fprintf(stdout, "review_verify.scope=%s\nreview_verify.state=%s\nreview_verify.fresh=%t\nreview_verify.approved=%t\nreview_verify.next_action=%s\n", verification.Scope, verification.State, verification.Fresh, verification.Approved, verification.NextAction)
		if verification.Round > 0 {
			render(stdout, stderr).Field("review_verify.round", fmt.Sprint(verification.Round))
		}
		if verification.Assurance != nil {
			render(stdout, stderr).Field("review_verify.assurance", posemodel.RenderReviewAssurance(*verification.Assurance))
		}
		// Why each criterion can or cannot be carried forward (spec
		// pose-material-equivalence-reuse), and where reused answers came from.
		if verification.Delta != nil {
			for _, e := range verification.Delta.CriterionReuse {
				line := e.Decision
				if len(e.ChangedInputs) > 0 {
					line += ": " + strings.Join(e.ChangedInputs, "; ")
				}
				render(stdout, stderr).Field("review_verify.reuse."+e.Criterion, line)
			}
		}
		if verification.Assurance != nil {
			for _, reuse := range verification.Assurance.Reuse {
				render(stdout, stderr).Field("review_verify.reused."+reuse.Criterion, "from "+reuse.FromAttestation+"; "+reuse.Mode+"; "+reuse.State)
			}
		}
		for _, run := range verification.DelegatedRuns {
			if run.Safety != nil {
				raw, _ := json.Marshal(run.Safety)
				render(stdout, stderr).Field("review_verify.safety."+run.RunID, string(raw))
			}
			render(stdout, stderr).Field("review_verify.run."+run.RunID, run.Adapter+" "+run.Status+" draft="+run.DraftDecision+" bundle="+run.BundleID+" reason="+run.Reason+fmt.Sprintf(" partial=%t resumes=%s limit_of=%s; ", run.Partial, run.Resumes, run.LimitOf)+run.Assurance)
			// The session lineage of a round (R6) and why a draft does not count (R4).
			if run.Thread != nil {
				lineage := fmt.Sprintf("round %d: %s session", run.Thread.Round, run.Thread.Mode)
				if run.Thread.Mode == posemodel.ReviewThreadContinued {
					lineage += " from " + run.Thread.From
				} else if run.Thread.Reason != "" {
					lineage += ": " + run.Thread.Reason
				}
				render(stdout, stderr).Field("review_verify.thread."+run.RunID, lineage)
			}
			for _, problem := range run.DraftProblems {
				render(stdout, stderr).Field("review_verify.draft_problem."+run.RunID, problem)
			}
		}
		for _, loss := range verification.DelegatedHistoryLosses {
			render(stdout, stderr).Field("review_verify.delegated_history_loss", loss)
		}
		for _, warning := range verification.Warnings {
			fmt.Fprintf(stdout, "[WARN] %s\n", warning)
		}
		for _, blocker := range verification.Blockers {
			fmt.Fprintf(stderr, "[ERROR] %s\n", blocker)
		}
	}
	if verification.State == "superseded" {
		noteUsageSignals(stdout, "supersession")
	}
	if verification.Attestation != nil && len(verification.Attestation.ReusedFrom) > 0 {
		noteUsageSignals(stdout, "criterion-reuse")
	}
	if !verification.Approved {
		return 1
	}
	return 0
}

