					slug, external, unresolved := s.CloseoutMemberTarget(raw)
					if unresolved != "" {
						return nil, fmt.Errorf("pose: %s", unresolved)
					}
					if !external {
						refs = append(refs, "spec:"+slug)
					}
				}
			}
		}
	} else if scope.Kind == "roadmap" {
		rm, err := s.GetRoadmap(scope.Slug)
