var slugPattern = regexp.MustCompile(`^[a-z0-9][a-z0-9._-]*$`)

// ValidateSlug rejects anything that could escape .pose/specs (path
// traversal) or that does not look like a POSE slug.
func ValidateSlug(slug string) error {
	if slug == "" || strings.Contains(slug, "..") || !slugPattern.MatchString(slug) {
		return fmt.Errorf("pose: invalid spec slug %q", slug)
	}
	return nil
}

// Store reads POSE artifacts from one project root (ADR-013: project-scoped).
type Store struct {
	reviewView         *reviewOperationView
	reviewTime         *time.Time
	reviewReuse        *reviewReuseTraversal
	onReviewVerify     func(scope string)
	Root               string // project root containing .pose/
	FederatedProjectID string
	FederatedResolver  *ArtifactResolver
	// closeoutChain is the chain of local aggregate scopes whose terminal
	// verification is asking for this one, through their dependency edges:
	// a scope already in it is a cycle and is not proven closed.
	closeoutChain []string
	// specs, when set, is the spec listing of one operation, read once
	// (spec pose-attention-within-a-second). Nil outside such an operation.
	specs *specSnapshot
	// indexPin, when set, is the one index generation an operation reads from
	// (spec pose-index-generation-integrity); see PinIndexes.
	indexPin *IndexGenerationView
	// FS is the filesystem of the operation this store serves (spec
	// pose-update-dry-run-reports-the-whole-update D2): nil reads and writes
	// the disk, a preview reads its staged view. A store built from this one
	// carries it on.
	FS Files
	// planWithoutCloseoutGate builds a review plan without asking the
	// closeout review gate, for the gate's own question about the plan's
	// effective independence (spec pose-closeout-review-policy-by-cost-benefit).
	planWithoutCloseoutGate bool
}

// fsys is the store's filesystem.
func (s Store) fsys() Files { return FilesOrNative(s.FS) }

// specSnapshot holds one read of the specs directory. GetSpec lists every
// spec to find one, and the obligation producers call it per spec, so a
// projection read every spec file once per spec per producer.
type specSnapshot struct {
	once  sync.Once
	specs []Spec
	err   error
	// bundleScopes maps a review bundle file to the scope its payload names,
	// read once per operation; ListReviewBundles otherwise decodes every
	// bundle for every scoped call.
	bundleScopes sync.Map
	// transfers is the listing of the project's transfer plans, read once per operation
	// (spec pose-index-input-binding-reads-each-transfer-once).
	transfersOnce sync.Once
	transfers     transferListing
}

// bundleScope returns the scope ref of the bundle file name in dir, reading
// it on first use. An unreadable bundle has no scope and matches nothing.
func (snapshot *specSnapshot) bundleScope(dir, name string) string {
	if scope, ok := snapshot.bundleScopes.Load(name); ok {
		return scope.(string)
	}
	scope := ""
	if raw, err := os.ReadFile(filepath.Join(dir, name)); err == nil {
		var header struct {
			Payload struct {
				Scope struct {
					Ref string `json:"ref"`
				} `json:"scope"`
			} `json:"payload"`
		}
		if json.Unmarshal(raw, &header) == nil {
			scope = header.Payload.Scope.Ref
		}
	}
	snapshot.bundleScopes.Store(name, scope)
	return scope
}

// withSpecSnapshot returns a store whose spec listing is read once and reused
// for the rest of the operation. Specs do not change during one read.
func (s Store) withSpecSnapshot() Store {
	s.specs = &specSnapshot{}
	return s
}

// cloneSpec copies the slices so no caller can change another's spec.
func cloneSpec(sp Spec) Spec {
	clone := func(values []string) []string {
		if values == nil {
			return nil
		}
		return append(make([]string, 0, len(values)), values...)
	}
	sp.DependsOn = clone(sp.DependsOn)
	sp.Remediates = clone(sp.Remediates)
	sp.Components = clone(sp.Components)
	sp.Delivers = clone(sp.Delivers)
	if sp.Priority != nil {
		priority := *sp.Priority
		sp.Priority = &priority
	}
	return sp
}

func (s Store) specsDir() string { return filepath.Join(s.Root, ".pose", "specs") }

// startWarnings reports the milestones named in the after: of the milestones a spec
// belongs to that hold no approval. Other forms of after: are not milestones of this
// roadmap, and readiness answers for them. A warning never refuses, so what cannot be
// read is a warning too.
func (s Store) startWarnings(spec string) []string {
	roadmaps, err := s.ListRoadmaps()
	if err != nil {
		return []string{"the milestones before this spec could not be read: " + err.Error()}
	}
	found := map[string]string{}
	for _, rm := range roadmaps {
		for _, milestone := range rm.Milestones {
			member := false
			for _, raw := range milestone.Specs {
				slug, external := s.canonicalMember(raw)
				member = member || !external && strings.TrimPrefix(slug, "spec:") == spec
			}
			if !member {
				continue
			}
			for _, after := range milestone.After {
				if !strings.Contains(after, ":") {
					after = "milestone:" + rm.Slug + "/" + after
				}
				ref, err := ParseArtifactRef(after)
				if err != nil || ref.Kind != "milestone" || ref.Project != "" {
					continue
				}
				if approved, err := s.scopeApproved(after); err != nil {
					found[after] = after + " comes before this spec and its approval could not be read: " + err.Error()
				} else if !approved {
					found[after] = after + " comes before this spec and is not closed: pose close " + after
				}
			}
		}
	}
	out := make([]string, 0, len(found))
	for _, warning := range found {
		out = append(out, warning)
	}
	sort.Strings(out)
	return out
}

