	sort.Slice(result, func(i, j int) bool {
		return result[i].Kind+"\x00"+result[i].Path+"\x00"+result[i].Digest < result[j].Kind+"\x00"+result[j].Path+"\x00"+result[j].Digest
	})
	return result
}

